/// The scope a command takes when `-s` is not given: `b` when it runs
/// in either side of a dual workspace, and `p` anywhere else, a plain
/// repo, a single-repo workspace, or a repo nested in a workspace's
/// tree that is neither side, so a default never reaches past the repo
/// the command is run in. The start is `-R`'s path, else the cwd.
///
/// A start that cannot be read defaults to `p`, and the resolver
/// behind the command reports the path.
pub fn default_repo_scope(repo: Option<&Path>) -> RepoScope {
    let start = match repo {
        Some(p) => p.canonicalize().ok(),
        None => std::env::current_dir().ok(),
    };
    let Some(start) = start else {
        return RepoScope::Por;
    };
    let Some(root) = find_workspace_root_from(&start) else {
        return RepoScope::Por;
    };
    let Ok(Some(bot)) = configured_bot_dir(&root) else {
        return RepoScope::Por;
    };
    // The repo the start is in, the nearest directory up holding a
    // `.jj` or `.git`, is the side the command acts from.
    let Some(enclosing) = start
        .ancestors()
        .find(|d| d.join(".jj").exists() || d.join(".git").exists())
    else {
        return RepoScope::Por;
    };
    let same = |p: &Path| p.canonicalize().is_ok_and(|p| p == enclosing);
    if same(&root) || same(&bot) {
        RepoScope::Sides(Scope(vec![Side::Work, Side::Bot]))
    } else {
        RepoScope::Por
    }
}

/// The scope `-s` names, or the default when it is not given
/// ([`default_repo_scope`]), the default said by `info!` under the
/// command's name so a default is never silent.
pub fn scope_or_default(given: Option<&RepoScope>, repo: Option<&Path>, cmd: &str) -> RepoScope {
    if let Some(s) = given {
        return s.clone();
    }
    let s = default_repo_scope(repo);
    let letter = match &s {
        RepoScope::Sides(sides) => scope_letter(sides),
        RepoScope::Por => "p",
    };
    info!("{cmd}: -s {letter}, the default");
    s
}

