474	            let err = move_bookmark(&mut test_ctx(), &params(&[w], "line", to)).unwrap_err();
475	            assert!(err.to_string().contains("exactly one"), "{to}: {err}");
476	        }
477	        let mut dry = params(&[w], "line", "@-");
478	        dry.dry_run = true;
479	        move_bookmark(&mut test_ctx(), &dry).expect("dry run");
480	        assert_eq!(commit_id(w, "line"), at);
481	    }
482	}
483

