1	//! The `delete-bookmark` subcommand: delete one bookmark locally and
2	//! on `origin`, the disposal a cycle's bookmark gets at Land, in one
3	//! invocation rather than `jj bookmark delete` and a `jj git push`.
4	//!
5	//! - The remote goes first, then the local, so a push that fails
6	//!   leaves the local bookmark, and a rerun finishes the job: a side
7	//!   already gone is no error.
8	//! - `--skip local` deletes the remote only, `--skip remote` the local
9	//!   only.
10	//! - The commits stay: jj keeps a commit visible after its bookmark is
11	//!   gone, so a deletion is undone by recreating the bookmark at the
12	//!   commit it prints.
13	//! - `-s w` deletes in the work repo, `-s a` in the agent repo, `-s b`
14	//!   in both, and `-s p` in the repo `-R` names, as it is.
15	//! - A failure restores the repo from a `jj op` snapshot when the
16	//!   remote was untouched.
17	
18	use std::path::{Path, PathBuf};
19	
20	use clap::Args;
21	use log::{debug, info, warn};
22	
23	use crate::context::Context;
24	use crate::jj;
25	use crate::options_flags::dry_run::DryRunFlag;
26	use crate::options_flags::scope::SCOPE_DEFAULT;
27	use crate::options_flags::scope::{
28	    ALL_REPO_SCOPES, REPO_SCOPE_FORMS, RepoScope, Side, repo_scope_parser,
29	};
30	use crate::pair::resolve_pair;
31	use crate::subcommand::SubcommandRunner;
32	
33	/// Which side of a bookmark `--skip` leaves.
34	#[derive(Clone, Copy, Debug, PartialEq, Eq, clap::ValueEnum)]
35	pub enum Keep {
36	    /// The local bookmark is kept, only `origin`'s deleted.
37	    Local,
38	    /// The remote bookmark is kept, only the local one deleted.
39	    Remote,
40	}
41	
42	/// Delete a bookmark locally and on `origin`.
43	#[derive(Args, Debug)]
44	pub struct DeleteBookmarkArgs {
45	    /// The bookmark to delete
46	    #[arg(long, value_name = "NAME", required = true)]
47	    pub bookmark: String,
48	
49	    /// Keep one side: `local` deletes only the remote, `remote` only
50	    /// the local
51	    #[arg(long, value_enum, value_name = "SIDE")]
52	    pub skip: Option<Keep>,
53	
54	    /// Where: a path in the workspace for `-s w|a|b`, or the repo
55	    /// itself for `-s p`, required there [default: the current
56	    /// directory]
57	    #[arg(short = 'R', long, value_name = "PATH")]
58	    pub repo: Option<PathBuf>,
59	
60	    /// Which repos
61	    #[arg(
62	        short = 's',
63	        long,
64	        value_name = "SCOPE",
65	        value_parser = repo_scope_parser(ALL_REPO_SCOPES),
66	        help = format!("Which repos: {REPO_SCOPE_FORMS}, `p` with -R {SCOPE_DEFAULT}")
67	    )]
68	    pub scope: Option<RepoScope>,
69	
70	    /// Print the deletions it would make, and change nothing
71	    #[command(flatten)]
72	    pub dry_run: DryRunFlag,
73	}
74	
75	/// Inputs to the delete-bookmark op, flat, owned, clap-free.
76	#[derive(Debug)]
77	pub struct DeleteBookmarkParams {
78	    pub repos: Vec<PathBuf>,
79	    pub bookmark: String,
80	    pub skip: Option<Keep>,
81	    pub dry_run: bool,
82	}
83	
84	impl TryFrom<&DeleteBookmarkArgs> for DeleteBookmarkParams {
85	    type Error = String;
86	
87	    /// Resolve the scope to its repos: `-R` as it is for `-s p`, the
88	    /// pair's sides for `-s w|a|b`.
89	    fn try_from(a: &DeleteBookmarkArgs) -> Result<Self, String> {
90	        let scope =
91	            crate::common::scope_or_default(a.scope.as_ref(), a.repo.as_deref(), "delete-bookmark");
92	        let repos = match &scope {
93	            RepoScope::Por => match &a.repo {
94	                Some(repo) => vec![repo.clone()],
95	                None => {
96	                    return Err("delete-bookmark -s p: -R is required, the repo to delete \
97	                                the bookmark in"
98	                        .into());
99	                }
100	            },
101	            RepoScope::Sides(sides) => {
102	                let pair = resolve_pair(a.repo.as_deref()).map_err(|e| e.to_string())?;
103	                sides
104	                    .0
105	                    .iter()
106	                    .map(|side| match side {
107	                        Side::Work => pair.work.clone(),
108	                        Side::Bot => pair.agent.clone(),
109	                    })
110	                    .collect()
111	            }
112	        };
113	        Ok(DeleteBookmarkParams {
114	            repos,
115	            bookmark: a.bookmark.clone(),
116	            skip: a.skip,
117	            dry_run: a.dry_run.value,
118	        })
119	    }
120	}
121	
122	impl SubcommandRunner for DeleteBookmarkArgs {
123	    type Params = DeleteBookmarkParams;
124	
125	    /// Delegate to the `TryFrom<&DeleteBookmarkArgs>` impl above.
126	    fn to_params(&self) -> Result<Self::Params, String> {
127	        DeleteBookmarkParams::try_from(self)
128	    }
129	
130	    /// Run the `delete-bookmark` op.
131	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
