//! `vc-x1 repo`: what is done to a workspace's repos as a whole, a
//! noun and its verbs as `cycle` and `rung` are. `delete` removes a
//! workspace from this machine, `rename` gives it a new name, and
//! `move` puts it in another directory.

pub mod delete;
pub mod relocate;
pub mod rename;

use std::process::ExitCode;

use clap::{Args, Subcommand};

use crate::context::Context;
use crate::subcommand::SubcommandRunner;

/// The `repo` command and its subcommand.
#[derive(Args, Debug)]
pub struct RepoArgs {
    #[command(subcommand)]
    pub command: RepoCommand,
}

/// The `repo` subcommands.
#[derive(Subcommand, Debug)]
pub enum RepoCommand {
    /// Remove a workspace from this machine
    #[command(
        long_about = "Remove a workspace from this machine: the work repo's directory, \
        the agent repo's when it is outside, and the Claude Code symlink when it points at the \
        agent repo. --local-repos also removes the bare repos the origins are when they are \
        paths here, and a remote reached by a URL is never touched. Work that is nowhere else, \
        uncommitted or unpushed, refuses unless --local-repos, which removes it all. The plan is \
        printed first, and --dry-run prints it alone."
    )]
    Delete(delete::DeleteArgs),
    /// Give a workspace a new name, its remote included
    #[command(
        long_about = "Give a workspace a new name, its remote included: the work repo's \
        directory, its origin's last segment, the agent remote when its name is the old one plus \
        a suffix, an agent directory outside the work repo the same way, both origin URLs, the \
        config's names for them, and the Claude Code symlink. What keeps the old name, the \
        family's names for it among them, is listed. Uncommitted or unpushed work, a new name \
        taken, a name GitHub would change, and an origin neither GitHub nor a bare repo here \
        refuse it before anything changes. The plan is printed first, and --dry-run prints it \
        alone."
    )]
    Rename(rename::RenameArgs),
    /// Move a workspace to another directory, its name kept
    #[command(
        long_about = "Move a workspace into DIR, its name kept: the work repo's directory \
        with the agent repo inside it, an origin that is a relative path rewritten for the new \
        place, and the Claude Code symlink made for the new root. No remote is touched. DIR \
        missing, the workspace there already, another filesystem, and an agent repo outside the \
        work repo refuse it before anything moves. The plan is printed first, and --dry-run \
        prints it alone."
    )]
    Move(relocate::MoveArgs),
}

impl RepoArgs {
    /// Run the subcommand asked for.
    pub fn dispatch(&self, ctx: &mut Context) -> ExitCode {
        match &self.command {
            RepoCommand::Delete(args) => args.dispatch(ctx),
            RepoCommand::Rename(args) => args.dispatch(ctx),
            RepoCommand::Move(args) => args.dispatch(ctx),
        }
    }
}

    /// Point an existing bookmark at one commit, locally, with -s
    #[command(long_about = "\
        Point one existing local bookmark at one commit, `jj bookmark set\n\
        <bookmark> -r <target>`, the repositioning a bookmark needs before\n\
        it is pushed, since push only sets the line's bookmark to @-.\n\
        Nothing is pushed.\n\n\
        --bookmark names a bookmark that must exist, none being created, and\n\
        --target a revset of exactly one commit, a bookmark or a rev. A move\n\
        backward or sideways is refused unless --allow-backwards, as jj\n\
        refuses it, and a bookmark already at the target is left alone.\n\n\
        -s is required: `w` the work repo, `a` the agent repo or `b` both with\n\
        --yes, the same name in each and the target resolved in each, every\n\
        repo checked before any moves. `p` takes the repo from -R, required,\n\
        as it is, with no workspace checks, so careful use is yours.")]
    MoveBookmark(move_bookmark::MoveBookmarkArgs),

    /// Delete a bookmark locally and on origin, with -s
    #[command(long_about = "\
        Delete one bookmark locally and on `origin`, the disposal a cycle's\n\
        bookmark gets at Land, `jj bookmark delete` and its push in one\n\
        invocation. The remote goes first, so a failed push leaves the local\n\
        bookmark, and a side already gone is no error, so a rerun finishes\n\
        the job. The commits stay, and the commit it was at is printed.\n\n\
        --skip local deletes only the remote, --skip remote only the local.\n\
        -s is required: `w` the work repo, `a` the agent repo, `b` both, and\n\
        `p` the repo -R names, as it is.")]
    DeleteBookmark(delete_bookmark::DeleteBookmarkArgs),

    /// Retired: `open`, now `cycle plan`, refused naming it.
    #[command(name = "open", hide = true, disable_help_flag = true)]
    OpenOld {
        /// Swallowed so the fix-it shows for any invocation.
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 0..)]
        rest: Vec<String>,
    },

    /// Run a cycle's stages: plan, ladder, status, close, squash, land, and push
    #[command(long_about = "\
        A cycle's stages, each a subcommand, beside `rung`'s acts: `plan\n\
        start` makes the bookmark and writes the record, `plan commit`\n\
        commits the plan, the opening, `rung next` and `rung commit` run\n\
        each work rung, `close` makes the\n\
        closing, `squash` makes the cycle one commit instead, `land` lands\n\
        it on a target, and `push` publishes what the\n\
        cycle's state calls for. `ladder` rewrites zTOC.md's ladder from the\n\
        rung headings, and `status` says where the cycle stands. A later\n\
        stage chains as a flag, `cycle close --land main --push`.\n\n\
        The version is the project's, and no stage writes it, `rung next\n\
        --ver` running the config's `[version] bump`. -R is optional and\n\
        says where, a workspace or a plain repo.")]
    Cycle(cycle::CycleArgs),

    /// Run a rung's acts: start the next, leave it, or commit it
    #[command(
        long_about = "A rung's acts, each a subcommand: `next` starts the next rung,\n\
        the first not done, marking it `(current)` in the working copy's\n\
        zTOC.md and with --ver setting the version by the config's\n\
        `[version] bump`, `stop` clears the marker, and `commit` commits\n\
        it, the ladder it carries marking it `(done)` and none current.\n\
        The marker is the working copy's alone, so no commit's tree claims\n\
        a rung not yet begun."
    )]
    Rung(cycle::rung::RungArgs),

    /// Retired: `land`, now `cycle land`, refused naming it.
    #[command(name = "land", hide = true, disable_help_flag = true)]
    LandOld {
        /// Swallowed so the fix-it shows for any invocation.
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 0..)]
        rest: Vec<String>,
    },

    /// Update the trailers of a range of work commits to what is stamped today
    #[command(long_about = "\
        Rewrite a range of work commits' trailers to what is stamped today,\n\
        only their descriptions changing, each tree checked unchanged.\n\n\
        `ochid:` becomes the partner's bare change id, an older 8 or 32\n\
        character id or a SHA naming one agent commit made its 12, and\n\
        `orepo:` above it names the agent repo by its `origin`'s canonical\n\
        URL, or `file:///` for a local one. An older commit's `ocid:` and\n\
        Commands::Merge(args) => args.dispatch(&mut ctx),
        Commands::MoveBookmark(args) => args.dispatch(&mut ctx),
        Commands::DeleteBookmark(args) => args.dispatch(&mut ctx),
        Commands::OpenOld { .. } => {
            error!(
                "open: retired, a cycle's acts being `vc-x1 cycle`'s: `vc-x1 cycle plan start --title \
                 \"<cycle title>\"` makes the bookmark and the record, and `--no-record` the \
                 bookmark alone."
            );
            ExitCode::FAILURE
        }
        Commands::Cycle(args) => args.dispatch(&mut ctx),
        Commands::Rung(args) => args.dispatch(&mut ctx),
        Commands::LandOld { .. } => {
            error!(
                "land: retired, a cycle's acts being `vc-x1 cycle`'s: `vc-x1 cycle land \
                 <BOOKMARK>` lands a closed cycle on the destination, `--bookmark` naming the \
                 cycle's when it is not the title's slug."
            );
            ExitCode::FAILURE
        }
        Commands::Trailers(args) => args.dispatch(&mut ctx),
    }

