1	//! The `move-bookmark` subcommand: point one existing local bookmark
2	//! at one commit, locally, the repositioning a bookmark needs before
3	//! it is pushed, since `push` only ever sets the line's bookmark to
4	//! the work `@-`.
5	//!
6	//! - The meaning is `jj bookmark set <bookmark> -r <target>`: the
7	//!   bookmark must already exist, and the target is a revset naming
8	//!   exactly one commit, a bookmark or a rev.
9	//! - A move along the bookmark's line, the target at or above where
10	//!   it points, is the normal case. A move backward or sideways is
11	//!   refused unless `--allow-backwards`, as `jj` refuses it, and a
12	//!   bookmark already at the target is left as it is.
13	//! - Nothing is pushed: publishing is `push`'s, with its approval.
14	//! - `-s w` moves a bookmark in the work repo. `-s a` in the agent
15	//!   repo and `-s b` in both take `--yes`, since the agent repo's
16	//!   `main` is otherwise push's agent half's to set: the same name in
17	//!   each, the target resolved in each, every repo checked before any
18	//!   moves, and a failure part-way restoring the ones moved.
19	//! - `-s p` takes the repo from `-R`, required, as it is, with none of
20	//!   the workspace's checks, so it can move a bookmark in either side
21	//!   of a dual workspace or in any jj repo. Careful use is the user's.
22	
23	use std::path::{Path, PathBuf};
24	
25	use clap::Args;
26	use log::{debug, info};
27	
28	use crate::context::Context;
29	use crate::jj;
30	use crate::options_flags::dry_run::DryRunFlag;
31	use crate::options_flags::scope::{
32	    ALL_REPO_SCOPES, REPO_SCOPE_FORMS, RepoScope, Side, repo_scope_parser,
33	};
34	use crate::pair::{Snapshot, resolve_pair};
35	use crate::subcommand::SubcommandRunner;
36	
37	/// Point an existing bookmark at one commit, locally.
38	#[derive(Args, Debug)]
39	pub struct MoveBookmarkArgs {
40	    /// The bookmark to move, which must already exist
41	    #[arg(long, value_name = "NAME", required = true)]
42	    pub bookmark: String,
43	
44	    /// Where it moves to, a revset of exactly one commit, a bookmark
45	    /// or a rev, resolved in each repo of the scope
46	    #[arg(long, value_name = "REV", required = true)]
47	    pub target: String,
48	
49	    /// Move it backward or sideways, as `jj` allows it
50	    #[arg(long)]
51	    pub allow_backwards: bool,
52	
53	    /// Where: a path in the workspace for `-s w|a|b`, or the repo
54	    /// itself for `-s p`, required there [default: the current
55	    /// directory]
56	    #[arg(short = 'R', long, value_name = "PATH")]
57	    pub repo: Option<PathBuf>,
58	
59	    /// Which repos, `w` by default in a dual workspace: `w|work`, `a|agent` or `b|both` with
60	    /// `--yes`, or `p|por` with `-R`
61	    #[arg(
62	        short = 's',
63	        long,
64	        value_name = "SCOPE",
65	        value_parser = repo_scope_parser(ALL_REPO_SCOPES),
66	        help = format!(
67	            "Which repos: {REPO_SCOPE_FORMS}, `a` and `b` with --yes, `p` with -R [default: `w` in either side of a dual workspace, `p` elsewhere]"
68	        )
69	    )]
70	    pub scope: Option<RepoScope>,
71	
72	    /// Move a bookmark in the agent repo, `-s a` or `-s b`
73	    #[arg(short = 'y', long)]
74	    pub yes: bool,
75	
76	    /// Print the move it would make, and change nothing
77	    #[command(flatten)]
78	    pub dry_run: DryRunFlag,
79	}
80	
81	/// Inputs to the move-bookmark op, flat, owned, clap-free.
82	#[derive(Debug)]
83	pub struct MoveBookmarkParams {
84	    pub repos: Vec<PathBuf>,
85	    pub bookmark: String,
86	    pub target: String,
87	    pub allow_backwards: bool,
88	    pub dry_run: bool,
89	}
90	
91	impl TryFrom<&MoveBookmarkArgs> for MoveBookmarkParams {
92	    type Error = String;
93	
94	    /// Resolve the scope to its repos: `-R` as it is for `-s p`, the
95	    /// pair's sides for `-s w|a|b`, the agent side only with `--yes`.
96	    fn try_from(a: &MoveBookmarkArgs) -> Result<Self, String> {
97	        let scope = crate::common::scope_or_default_dual(
98	            a.scope.as_ref(),
99	            a.repo.as_deref(),
100	            "move-bookmark",
101	            &[crate::options_flags::scope::Side::Work],
102	        );
103	        let repos = match &scope {
104	            RepoScope::Por => match &a.repo {
105	                Some(repo) => vec![repo.clone()],
106	                None => {
107	                    return Err("move-bookmark -s p: -R is required, the repo to move the \
108	                                bookmark in, taken as it is with no workspace checks"
109	                        .into());
110	                }
111	            },
112	            RepoScope::Sides(sides) => {
113	                if sides.has_bot() && !a.yes {
114	                    return Err("move-bookmark: -s a and -s b move a bookmark in the agent \
115	                                repo, whose `main` is otherwise push's agent half's to set. \
116	                                Pass --yes to move it"
117	                        .into());
118	                }
119	                let pair = resolve_pair(a.repo.as_deref()).map_err(|e| e.to_string())?;
120	                sides
121	                    .0
122	                    .iter()
123	                    .map(|side| match side {
124	                        Side::Work => pair.work.clone(),
125	                        Side::Bot => pair.agent.clone(),
126	                    })
127	                    .collect()
128	            }
129	        };
130	        Ok(MoveBookmarkParams {
131	            repos,
132	            bookmark: a.bookmark.clone(),
133	            target: a.target.clone(),
134	            allow_backwards: a.allow_backwards,
135	            dry_run: a.dry_run.value,
136	        })
137	    }
138	}
139	
140	impl SubcommandRunner for MoveBookmarkArgs {
141	    type Params = MoveBookmarkParams;
142	
143	    /// Delegate to the `TryFrom<&MoveBookmarkArgs>` impl above.
144	    fn to_params(&self) -> Result<Self::Params, String> {
145	        MoveBookmarkParams::try_from(self)
146	    }
147	
148	    /// Run the `move-bookmark` op.
149	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
150	        move_bookmark(ctx, params)
151	    }
152	}
153	
154	/// One repo's move: where the bookmark points, a conflicted one at
155	/// several commits, and the commit it moves to.
156	#[derive(Debug)]
157	struct Move {
158	    repo: PathBuf,
159	    from: Vec<String>,
160	    to: String,
161	}
162	
163	impl Move {
164	    /// True when the bookmark already points at the target alone.
165	    fn is_noop(&self) -> bool {
166	        self.from == [self.to.clone()]
167	    }
168	
169	    /// The commits it points at, 12 characters each, joined.
170	    fn shown_from(&self) -> String {
171	        self.from
172	            .iter()
173	            .map(|id| short(id))
174	            .collect::<Vec<_>>()
175	            .join(", ")
176	    }
177	}
178	
179	/// The 12-character form of a commit id.
180	fn short(id: &str) -> String {
181	    id[..id.len().min(12)].to_string()
182	}
183	
184	/// Check one repo's move, refusing a bookmark that does not exist, a
185	/// target that is not one commit, and a backward or sideways move
186	/// unless `allow_backwards`.
187	fn plan(
188	    repo: &Path,
189	    name: &str,
190	    target: &str,
191	    allow_backwards: bool,
192	) -> Result<Move, Box<dyn std::error::Error>> {
193	    if !jj::local_bookmark_exists(repo, name)? {
194	        return Err(format!(
195	            "move-bookmark: the bookmark '{name}' does not exist in {}, and move-bookmark \
196	             creates none",
197	            repo.display()
198	        )
199	        .into());
200	    }
201	    let to = match jj::cids_of(repo, target)?.as_slice() {
202	        [one] => one.clone(),
203	        other => {
204	            return Err(format!(
205	                "move-bookmark: the target '{target}' names {} commits in {}, and a bookmark \
206	                 points at exactly one",
207	                other.len(),
208	                repo.display()
209	            )
210	            .into());
211	        }
212	    };
213	    let at = format!("bookmarks(exact:{name:?})");
214	    let mv = Move {
215	        repo: repo.to_path_buf(),
216	        from: jj::cids_of(repo, &at)?,
217	        to,
218	    };
219	    // Forward when every commit the bookmark points at, a conflicted
220	    // one's included, is an ancestor of the target.
221	    let forward = !jj::matches(repo, &format!("{at} ~ ::{}", mv.to))?;
222	    if !mv.is_noop() && !forward && !allow_backwards {
223	        return Err(format!(
224	            "move-bookmark: moving '{name}' from {} to {} in {} is backward or sideways, \
225	             leaving commits off its line. Pass --allow-backwards to move it anyway",
226	            mv.shown_from(),
227	            short(&mv.to),
228	            repo.display()
229	        )
230	        .into());
231	    }
232	    Ok(mv)
233	}
234	
235	/// Move the bookmark to the target in each repo of the scope, every
236	/// repo checked before any moves, and a failure restoring the repos
237	/// already moved.
238	pub fn move_bookmark(
239	    ctx: &mut Context,
240	    params: &MoveBookmarkParams,
241	) -> Result<(), Box<dyn std::error::Error>> {
242	    debug!("move-bookmark: enter {params:?}");
243	    let name = &params.bookmark;
244	    let mut moves = Vec::with_capacity(params.repos.len());
245	    for repo in &params.repos {
246	        moves.push(plan(repo, name, &params.target, params.allow_backwards)?);
247	    }
248	    let dry = if params.dry_run {
249	        "[dry-run] would move"
250	    } else {
251	        "moving"
252	    };
253	    let mut moved: Vec<Snapshot> = Vec::new();
254	    for mv in &moves {
255	        if mv.is_noop() {
256	            info!(
257	                "move-bookmark: '{name}' is already at {}, so nothing changes, in {}",
258	                short(&mv.to),
259	                mv.repo.display()
260	            );
261	            continue;
262	        }
263	        info!(
264	            "move-bookmark: {dry} '{name}' from {} to {}, locally, in {}",
265	            mv.shown_from(),
266	            short(&mv.to),
267	            mv.repo.display()
268	        );
269	        if params.dry_run {
270	            continue;
271	        }
272	        let snapshot = Snapshot::take(&mv.repo)?;
273	        if let Err(e) = ctx.session(&mv.repo)?.bookmark_set(name, &mv.to) {
274	            for s in moved.iter().rev() {
275	                s.restore("move-bookmark", e.as_ref());
276	            }
277	            return Err(e);
278	        }
279	        moved.push(snapshot);
280	    }
281	    Ok(())
282	}
