84	impl TryFrom<&DeleteBookmarkArgs> for DeleteBookmarkParams {
85	    type Error = String;
86	
87	    /// Resolve the scope to its repos: `-R` as it is for `-s p`, the
88	    /// pair's sides for `-s w|a|b`.
89	    fn try_from(a: &DeleteBookmarkArgs) -> Result<Self, String> {
90	        let scope =
91	            crate::common::scope_or_default(a.scope.as_ref(), a.repo.as_deref(), "delete-bookmark");
92	        let repos = match &scope {
93	            RepoScope::Por => match &a.repo {
94	                Some(repo) => vec![repo.clone()],
95	                None => {
96	                    return Err("delete-bookmark -s p: -R is required, the repo to delete \
97	                                the bookmark in"
98	                        .into());
99	                }
100	            },
101	            RepoScope::Sides(sides) => {
102	                let pair = resolve_pair(a.repo.as_deref()).map_err(|e| e.to_string())?;
103	                sides
104	                    .0
105	                    .iter()
106	                    .map(|side| match side {
107	                        Side::Work => pair.work.clone(),
108	                        Side::Bot => pair.agent.clone(),
109	                    })
110	                    .collect()
111	            }
112	        };
113	        Ok(DeleteBookmarkParams {
114	            repos,
115	            bookmark: a.bookmark.clone(),
116	            skip: a.skip,
117	            dry_run: a.dry_run.value,
118	        })
