140	/// Delete `name` in `repo`, the remote then the local, `skip` keeping
141	/// one side, printing the commit it was at so the deletion can be
142	/// undone. A side already gone is no error, and a bookmark gone on
143	/// both sides is reported and left.
144	pub fn delete_bookmark(
145	    ctx: &mut Context,
146	    repo: &Path,
147	    name: &str,
148	    skip: Option<Keep>,
149	    dry_run: bool,
150	) -> Result<(), Box<dyn std::error::Error>> {
151	    let local = jj::local_bookmark_exists(repo, name)?;
152	    let remote = jj::remote_bookmark_targets(repo, "origin")?
153	        .get(name)
154	        .cloned();
155	    let at = if local {
156	        Some(jj::cid_of(repo, name)?)
157	    } else {
158	        remote.clone()
159	    };
160	    let (del_remote, del_local) = (
161	        remote.is_some() && skip != Some(Keep::Remote),
162	        local && skip != Some(Keep::Local),
163	    );
164	    if !del_remote && !del_local {
165	        warn!(
166	            "delete-bookmark: '{name}' has nothing to delete in {}, as asked",
167	            repo.display()
168	        );
169	        return Ok(());
170	    }
171	    let at = at.unwrap_or_default();
172	    let dry = if dry_run { "[dry-run] " } else { "" };
173	    if del_remote {
174	        info!("delete-bookmark: {dry}delete '{name}' on origin, at {at}");
175	    }
176	    if del_local {
177	        info!("delete-bookmark: {dry}delete '{name}' locally, at {at}");
178	    }
179	    if dry_run {
180	        return Ok(());
181	    }
182	    if del_remote {
183	        ctx.session(repo)?.git_push_delete_bookmark(name)?;
184	    }
185	    if del_local {
186	        ctx.session(repo)?.bookmark_delete(name)?;
187	    }
188	    info!("delete-bookmark: done, `jj bookmark set {name} -r {at}` would bring it back");
189	    Ok(())
190	}
