//! `vc-x1 bookmark`: a bookmark's verbs, a noun and its verbs as
//! `repo`, `cycle`, and `rung` are, each value a positional. `create`
//! makes one, `move` points one at another commit, `rename` gives one a
//! new name, and `delete` removes one, locally and on `origin`.
//!
//! - The scope defaults to `w` in either side of a dual workspace, the
//!   work repo being where a cycle's bookmarks live, the agent repo
//!   needing none, and to `p` elsewhere, `-R` naming the repo.
//! - A verb that moves or renames a bookmark in the agent repo takes
//!   `--yes`, since its `main` is otherwise push's agent half's to set.
//! - Only `delete`, and `rename --push`, reach `origin`. The rest are
//!   local, publishing being `push`'s.

pub mod create;
pub mod delete;
pub mod mv;
pub mod rename;

use std::path::PathBuf;
use std::process::ExitCode;

use clap::{Args, Subcommand};

use crate::context::Context;
use crate::options_flags::scope::{RepoScope, Side};
use crate::pair::resolve_pair;
use crate::subcommand::SubcommandRunner;

/// The default a bookmark verb's `-s` help names.
pub const BOOKMARK_SCOPE_DEFAULT: &str =
    "[default: `w` in either side of a dual workspace, `p` elsewhere]";

/// The `bookmark` command and its subcommand.
#[derive(Args, Debug)]
pub struct BookmarkArgs {
    #[command(subcommand)]
    pub command: BookmarkCommand,
}

/// The `bookmark` subcommands.
#[derive(Subcommand, Debug)]
pub enum BookmarkCommand {
    /// Make a bookmark at one commit, locally
    #[command(long_about = "\
        Make a new local bookmark NAME at REV, a revset of exactly one\n\
        commit, `@` when not given, as `jj bookmark create` does. A name\n\
        in use is refused, `bookmark move` being for that. Nothing is\n\
        pushed.\n\n\
        -s is optional: `w` the work repo, its default in a dual workspace,\n\
        `a` the agent repo, `b` both, the target resolved in each and every\n\
        repo checked before any is made, and `p` the repo -R names, as it\n\
        is.")]
    Create(create::CreateArgs),
    /// Delete a bookmark locally and on origin
    #[command(long_about = "\
        Delete one bookmark locally and on `origin`, the disposal a cycle's\n\
        bookmark gets at Land, `jj bookmark delete` and its push in one\n\
        invocation. The remote goes first, so a failed push leaves the local\n\
        bookmark, and a side already gone is no error, so a rerun finishes\n\
        the job. The commits stay, and the commit it was at is printed.\n\n\
        --skip local deletes only the remote, --skip remote only the local.\n\
        -s is optional: `w` the work repo, its default in a dual workspace,\n\
        `a` the agent repo, `b` both, and `p` the repo -R names, as it is.")]
    Delete(delete::DeleteArgs),
    /// Point an existing bookmark at one commit, locally
    #[command(long_about = "\
        Point one existing local bookmark at one commit, `jj bookmark set\n\
        <NAME> -r <TARGET>`, the repositioning a bookmark needs before\n\
        it is pushed, since push only sets the line's bookmark to @-.\n\
        Nothing is pushed.\n\n\
        NAME must exist, none being created, and TARGET is a revset of\n\
        exactly one commit, a bookmark or a rev. A move backward or\n\
        sideways is refused unless --allow-backwards, as jj refuses it, and\n\
        a bookmark already at the target is left alone.\n\n\
        -s is optional: `w` the work repo, its default in a dual workspace,\n\
        `a` the agent repo or `b` both with --yes, the same name in each and\n\
        the target resolved in each, every repo checked before any moves.\n\
        `p` takes the repo from -R, required, as it is, with no workspace\n\
        checks, so careful use is yours.")]
    Move(mv::MoveArgs),
    /// Give a bookmark a new name, locally, and on origin with --push
    #[command(long_about = "\
        Give the local bookmark OLD the name NEW, at the commit OLD is at,\n\
        as `jj bookmark rename` does. NEW in use, or OLD missing, is refused\n\
        before anything changes.\n\n\
        A published OLD stays on `origin` under its old name unless --push,\n\
        which pushes NEW and then deletes OLD there, a publish that takes\n\
        its own approval.\n\n\
        -s is optional: `w` the work repo, its default in a dual workspace,\n\
        `a` the agent repo or `b` both with --yes, every repo checked before\n\
        any is renamed, and `p` the repo -R names, as it is.")]
    Rename(rename::RenameArgs),
}

impl BookmarkArgs {
    /// Run the subcommand asked for.
    pub fn dispatch(&self, ctx: &mut Context) -> ExitCode {
        match &self.command {
            BookmarkCommand::Create(args) => args.dispatch(ctx),
            BookmarkCommand::Delete(args) => args.dispatch(ctx),
            BookmarkCommand::Move(args) => args.dispatch(ctx),
            BookmarkCommand::Rename(args) => args.dispatch(ctx),
        }
    }
}

/// The repos a bookmark verb acts in, by `-s`, its default `w` in
/// either side of a dual workspace and `p` elsewhere: `-R` as it is for
/// `p`, required there, and the pair's sides for `w|a|b`, the agent
/// side only with `yes` when `guard` names why it takes it.
pub fn bookmark_repos(
    scope: Option<&RepoScope>,
    repo: Option<&std::path::Path>,
    label: &str,
    guard: Option<(&str, bool)>,
) -> Result<Vec<PathBuf>, String> {
    let scope = crate::common::scope_or_default(scope, repo, label, &[Side::Work]);
    match &scope {
        RepoScope::Por => match repo {
            Some(repo) => Ok(vec![repo.to_path_buf()]),
            None => Err(format!(
                "{label} -s p: -R is required, the repo to act in, taken as it is with no \
                 workspace checks"
            )),
        },
        RepoScope::Sides(sides) => {
            if let Some((why, yes)) = guard
                && sides.has_bot()
                && !yes
            {
                return Err(format!(
                    "{label}: -s a and -s b {why} in the agent repo, whose `main` is otherwise \
                     push's agent half's to set. Pass --yes to do it"
                ));
            }
            let pair = resolve_pair(repo).map_err(|e| e.to_string())?;
            Ok(sides
                .0
                .iter()
                .map(|side| match side {
                    Side::Work => pair.work.clone(),
                    Side::Bot => pair.agent.clone(),
                })
                .collect())
        }
    }
}

/// The 12-character form of a commit id.
pub fn short(id: &str) -> String {
    id[..id.len().min(12)].to_string()
}

