        A published OLD stays on `origin` under its old name unless --push,\n\
        which pushes NEW and then deletes OLD there, a publish that takes\n\
        its own approval.\n\n\
        -s is optional: `w` the work repo, its default in a dual workspace,\n\
        `a` the agent repo or `b` both with --yes, every repo checked before\n\
        any is renamed, and `p` the repo -R names, as it is.")]
    Rename(rename::RenameArgs),
}

impl BookmarkArgs {
    /// Run the subcommand asked for.
    pub fn dispatch(&self, ctx: &mut Context) -> ExitCode {
        match &self.command {
            BookmarkCommand::Create(args) => args.dispatch(ctx),
            BookmarkCommand::Delete(args) => args.dispatch(ctx),
            BookmarkCommand::Move(args) => args.dispatch(ctx),
            BookmarkCommand::Rename(args) => args.dispatch(ctx),
        }
    }
}

/// The repos a bookmark verb acts in, by `-s`, its default `w` in
/// either side of a dual workspace and `p` elsewhere: `-R` as it is for
/// `p`, required there, and the pair's sides for `w|a|b`, the agent
/// side only with `yes` when `guard` names why it takes it.
pub fn bookmark_repos(
    scope: Option<&RepoScope>,
    repo: Option<&std::path::Path>,
    label: &str,
    guard: Option<(&str, bool)>,
) -> Result<Vec<PathBuf>, String> {
    let scope = crate::common::scope_or_default(scope, repo, label, &[Side::Work]);
    match &scope {
        RepoScope::Por => match repo {
            Some(repo) => Ok(vec![repo.to_path_buf()]),
            None => Err(format!(
                "{label} -s p: -R is required, the repo to act in, taken as it is with no \
                 workspace checks"
            )),
        },
        RepoScope::Sides(sides) => {
            if let Some((why, yes)) = guard
                && sides.has_bot()
                && !yes
            {
                return Err(format!(
                    "{label}: -s a and -s b {why} in the agent repo, whose `main` is otherwise \
                     push's agent half's to set. Pass --yes to do it"
                ));
            }
            let pair = resolve_pair(repo).map_err(|e| e.to_string())?;
            Ok(sides
                .0
                .iter()
                .map(|side| match side {
                    Side::Work => pair.work.clone(),
                    Side::Bot => pair.agent.clone(),
                })
                .collect())
        }
    }
}

/// The 12-character form of a commit id.
pub fn short(id: &str) -> String {
    id[..id.len().min(12)].to_string()
}

