//! `vc-x1 bookmark create NAME [REV]`: make a new local bookmark at
//! one commit, `jj bookmark create NAME -r REV`, `@` when REV is not
//! given, as jj's own default.
//!
//! - A name in use is refused, `bookmark move` being for that, and REV
//!   names exactly one commit.
//! - `-s w`, the default in a dual workspace, makes it in the work
//!   repo, `-s a` in the agent repo, `-s b` in both, the target
//!   resolved in each and every repo checked before any is made, and
//!   `-s p` in the repo `-R` names, as it is.
//! - Nothing is pushed.

use std::path::PathBuf;

use clap::Args;
use log::{debug, info};

use super::{BOOKMARK_SCOPE_DEFAULT, bookmark_repos, short};
use crate::context::Context;
use crate::jj;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{ALL_REPO_SCOPES, REPO_SCOPE_FORMS, RepoScope, repo_scope_parser};
use crate::pair::Snapshot;
use crate::subcommand::SubcommandRunner;

/// What a bookmark verb's messages are named by.
const LABEL: &str = "bookmark create";

/// Make a bookmark at one commit, locally.
#[derive(Args, Debug)]
pub struct CreateArgs {
    /// The bookmark to make, a name not in use
    #[arg(value_name = "NAME")]
    pub bookmark: String,

    /// Where it is made, a revset of exactly one commit, resolved in
    /// each repo of the scope
    #[arg(value_name = "REV", default_value = "@")]
    pub rev: String,

    /// Where: a path in the workspace for `-s w|a|b`, or the repo
    /// itself for `-s p`, required there [default: the current
    /// directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Which repos, `w` the default in a dual workspace
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = repo_scope_parser(ALL_REPO_SCOPES),
        help = format!("Which repos: {REPO_SCOPE_FORMS}, `p` with -R {BOOKMARK_SCOPE_DEFAULT}")
    )]
    pub scope: Option<RepoScope>,

    /// Print the bookmark it would make, and change nothing
    #[command(flatten)]
    pub dry_run: DryRunFlag,
}

/// Inputs to the `bookmark create` op, flat, owned, clap-free.
#[derive(Debug)]
pub struct CreateParams {
    pub repos: Vec<PathBuf>,
    pub bookmark: String,
    pub rev: String,
    pub dry_run: bool,
}

impl SubcommandRunner for CreateArgs {
    type Params = CreateParams;

    /// Resolve the scope to its repos ([`bookmark_repos`]).
    fn to_params(&self) -> Result<Self::Params, String> {
        Ok(CreateParams {
            repos: bookmark_repos(self.scope.as_ref(), self.repo.as_deref(), LABEL, None)?,
            bookmark: self.bookmark.clone(),
            rev: self.rev.clone(),
            dry_run: self.dry_run.value,
        })
    }

    /// Run the `bookmark create` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        create(ctx, params)
    }
}

/// Make the bookmark in each repo of the scope, every repo checked
/// first, the name not in use and the rev one commit, and a failure
/// part-way restoring the repos already made in.
pub fn create(ctx: &mut Context, params: &CreateParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("{LABEL}: enter {params:?}");
    let name = &params.bookmark;
    let mut at = Vec::with_capacity(params.repos.len());
    for repo in &params.repos {
        if jj::local_bookmark_exists(repo, name)? {
            return Err(format!(
                "{LABEL}: '{name}' is in use in {}, and `bookmark move` moves one",
                repo.display()
            )
            .into());
        }
        match jj::cids_of(repo, &params.rev)?.as_slice() {
            [one] => at.push((repo, one.clone())),
            other => {
                return Err(format!(
                    "{LABEL}: '{}' names {} commits in {}, and a bookmark points at exactly one",
                    params.rev,
                    other.len(),
                    repo.display()
                )
                .into());
            }
        }
    }
    let dry = if params.dry_run {
        "[dry-run] would make"
    } else {
        "making"
    };
