    for (repo, id) in at {
        info!(
            "{LABEL}: {dry} '{name}' at {}, locally, in {}",
            short(&id),
            repo.display()
        );
        if params.dry_run {
            continue;
        }
        let snapshot = Snapshot::take(repo)?;
        if let Err(e) = ctx.session(repo)?.bookmark_set(name, &id) {
            for s in made.iter().rev() {
                s.restore(LABEL, e.as_ref());
            }
            return Err(e);
        }
        made.push(snapshot);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_helpers::{Fixture, jj_ok, test_ctx};

    fn commit_id(repo: &std::path::Path, rev: &str) -> String {
        jj_ok(repo, &["log", "-r", rev, "--no-graph", "-T", "commit_id"])
    }

    fn params(repos: &[&std::path::Path], name: &str, rev: &str) -> CreateParams {
        CreateParams {
            repos: repos.iter().map(|r| r.to_path_buf()).collect(),
            bookmark: name.to_string(),
            rev: rev.to_string(),
            dry_run: false,
        }
    }

    /// A bookmark is made at the rev in each repo, a name in use and a
    /// rev of no commit or several refused before any is made, and a
    /// dry run makes none.
    #[test]
    fn a_bookmark_is_made_at_one_commit() {
        let fx = Fixture::new("bm-create");
        let (w, a) = (fx.work.as_path(), fx.bot.as_path());
        let mut dry = params(&[w], "line", "@-");
        dry.dry_run = true;
        create(&mut test_ctx(), &dry).expect("dry run");
        assert!(!jj::local_bookmark_exists(w, "line").unwrap());

        create(&mut test_ctx(), &params(&[w], "line", "@-")).expect("made");
        assert_eq!(commit_id(w, "line"), commit_id(w, "@-"));
        let err = create(&mut test_ctx(), &params(&[w], "line", "@")).unwrap_err();
        assert!(err.to_string().contains("in use"), "{err}");
        for rev in ["none()", "@- | @"] {
            let err = create(&mut test_ctx(), &params(&[w], "other", rev)).unwrap_err();
            assert!(err.to_string().contains("exactly one"), "{rev}: {err}");
        }

