        let err = create(&mut test_ctx(), &params(&[a, w], "line", "@-")).unwrap_err();
        assert!(err.to_string().contains("in use"), "{err}");
        assert!(!jj::local_bookmark_exists(a, "line").unwrap());
        create(&mut test_ctx(), &params(&[w, a], "both", "@-")).expect("both");
        assert_eq!(commit_id(a, "both"), commit_id(a, "@-"));
    }
