//! `vc-x1 bookmark rename OLD NEW`: give a local bookmark a new name
//! at the commit it is at, as `jj bookmark rename` does.
//!
//! - OLD missing, or NEW in use, is refused in every repo of the scope
//!   before any is renamed.
//! - Local by default: a published OLD stays on `origin` under its old
//!   name, and is said so. `--push` renames it there too, pushing NEW
//!   and then deleting OLD on `origin`, a publish taking its own
//!   approval, the local OLD deleted last, so a failed push leaves OLD
//!   where it was and the step it stopped at named.
//! - `-s w`, the default in a dual workspace, renames in the work repo,
//!   `-s a` in the agent repo and `-s b` in both take `--yes`, and `-s
//!   p` renames in the repo `-R` names, as it is.

use std::path::{Path, PathBuf};

use clap::Args;
use log::{debug, info};

use super::{BOOKMARK_SCOPE_DEFAULT, bookmark_repos, short};
use crate::context::Context;
use crate::jj;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{ALL_REPO_SCOPES, REPO_SCOPE_FORMS, RepoScope, repo_scope_parser};
use crate::subcommand::SubcommandRunner;

/// What a bookmark verb's messages are named by.
const LABEL: &str = "bookmark rename";

/// Give a bookmark a new name, locally, and on `origin` with `--push`.
#[derive(Args, Debug)]
pub struct RenameArgs {
    /// The bookmark's name now
    #[arg(value_name = "OLD")]
    pub old: String,

    /// Its new name, not in use
    #[arg(value_name = "NEW")]
    pub new: String,

    /// Rename it on `origin` too, pushing NEW and deleting OLD there
    #[arg(long)]
