        rename(&mut test_ctx(), &dry).expect("dry run");
        assert_eq!(state(w, "one"), (true, false));

        rename(&mut test_ctx(), &params(&[w], "one", "two", false)).expect("local");
        assert_eq!(state(w, "one"), (false, false));
        assert_eq!(jj::cid_of(w, "two").unwrap(), at);
        let err = rename(&mut test_ctx(), &params(&[w], "one", "three", false)).unwrap_err();
        assert!(err.to_string().contains("no local bookmark"), "{err}");
        let err = rename(&mut test_ctx(), &params(&[w], "two", "main", false)).unwrap_err();
        assert!(err.to_string().contains("in use"), "{err}");

        jj_ok(w, &["git", "push", "--bookmark", "two"]);
        rename(&mut test_ctx(), &params(&[w], "two", "kept", false)).expect("local only");
        assert_eq!(state(w, "kept"), (true, false));
        assert!(state(w, "two").1, "the old name stays on origin");

        jj_ok(w, &["bookmark", "create", "pub", "-r", "@-"]);
        jj_ok(w, &["git", "push", "--bookmark", "pub"]);
        rename(&mut test_ctx(), &params(&[w], "pub", "moved", true)).expect("with --push");
        assert_eq!(state(w, "pub"), (false, false));
        assert_eq!(state(w, "moved"), (true, true));
    }
}

