//! A retired flag: a value a command cannot run without became a
//! positional, in the order the command reads, and the flag is kept as
//! a hidden argument and refused with the positional form, rather than
//! with clap's generic unexpected-argument error. A stale doc or a
//! habit is told its own fix. The mirror of
//! [`retired_positional`](super::retired_positional).

/// The refusal for `flag` on `command`, given, naming `form`, the
/// positional usage that replaced it.
pub fn refusal(command: &str, flag: &str, form: &str) -> String {
    format!("{command} {flag}: retired, the value a positional now: `{command} {form}`")
}

/// The first of `flags`, each `(flag, given)`, that was given, refused
/// naming `form`, and nothing to refuse when none was.
pub fn refuse_any(command: &str, flags: &[(&str, bool)], form: &str) -> Result<(), String> {
    match flags.iter().find(|(_, given)| *given) {
        Some((flag, _)) => Err(refusal(command, flag, form)),
        None => Ok(()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The refusal names the command, the flag, and the positional form.
    #[test]
    fn refusal_names_the_positional_form() {
        assert_eq!(
            refusal("merge", "--target", "TARGET FROM..."),
            "merge --target: retired, the value a positional now: `merge TARGET FROM...`"
        );
        assert_eq!(refuse_any("merge", &[("--target", false)], "T"), Ok(()));
        let err = refuse_any("merge", &[("--target", false), ("--from", true)], "T").unwrap_err();
        assert!(err.starts_with("merge --from:"), "{err}");
    }
}

