            return Err("lookup: --line FILE:LINE names the line to look up".into());
        };
        let (file, line) = parse_file_line(target)?;
        if a.tolerance < 0 {
            return Err("lookup: --tolerance is a number of seconds, so not negative".into());
        }
        Ok(LookupParams {
            side: a.scope,
            file,
