1	//! `vc-x1 bookmark delete NAME`: delete one bookmark locally and on
2	//! `origin`, the disposal a cycle's bookmark gets at Land, in one
3	//! invocation rather than `jj bookmark delete` and a `jj git push`.
4	//!
5	//! - The remote goes first, then the local, so a push that fails
6	//!   leaves the local bookmark, and a rerun finishes the job: a side
7	//!   already gone is no error.
8	//! - `--skip local` deletes the remote only, `--skip remote` the local
9	//!   only.
10	//! - The commits stay: jj keeps a commit visible after its bookmark is
11	//!   gone, so a deletion is undone by recreating the bookmark at the
12	//!   commit it prints.
13	//! - `-s w`, the default in a dual workspace, deletes in the work repo,
14	//!   `-s a` in the agent repo, `-s b` in both, and `-s p` in the repo
15	//!   `-R` names, as it is.
16	//! - A failure restores the repo from a `jj op` snapshot when the
17	//!   remote was untouched.
18	
19	use std::path::{Path, PathBuf};
20	
21	use clap::Args;
22	use log::{debug, info, warn};
23	
24	use super::{BOOKMARK_SCOPE_DEFAULT, bookmark_repos};
25	use crate::context::Context;
26	use crate::jj;
27	use crate::options_flags::dry_run::DryRunFlag;
28	use crate::options_flags::scope::{
29	    ALL_REPO_SCOPES, REPO_SCOPE_FORMS, RepoScope, repo_scope_parser,
30	};
31	use crate::subcommand::SubcommandRunner;
32	
33	/// What a bookmark verb's messages are named by.
34	const LABEL: &str = "bookmark delete";
35	
36	/// Which side of a bookmark `--skip` leaves.
37	#[derive(Clone, Copy, Debug, PartialEq, Eq, clap::ValueEnum)]
38	pub enum Keep {
39	    /// The local bookmark is kept, only `origin`'s deleted.
40	    Local,
41	    /// The remote bookmark is kept, only the local one deleted.
42	    Remote,
43	}
44	
45	/// Delete a bookmark locally and on `origin`.
46	#[derive(Args, Debug)]
47	pub struct DeleteArgs {
48	    /// The bookmark to delete
49	    #[arg(value_name = "NAME")]
50	    pub bookmark: String,
51	
52	    /// Keep one side: `local` deletes only the remote, `remote` only
53	    /// the local
54	    #[arg(long, value_enum, value_name = "SIDE")]
55	    pub skip: Option<Keep>,
56	
57	    /// Where: a path in the workspace for `-s w|a|b`, or the repo
58	    /// itself for `-s p`, required there [default: the current
59	    /// directory]
60	    #[arg(short = 'R', long, value_name = "PATH")]
61	    pub repo: Option<PathBuf>,
62	
63	    /// Which repos, `w` the default in a dual workspace
64	    #[arg(
65	        short = 's',
66	        long,
67	        value_name = "SCOPE",
68	        value_parser = repo_scope_parser(ALL_REPO_SCOPES),
69	        help = format!("Which repos: {REPO_SCOPE_FORMS}, `p` with -R {BOOKMARK_SCOPE_DEFAULT}")
70	    )]
71	    pub scope: Option<RepoScope>,
72	
73	    /// Print the deletions it would make, and change nothing
74	    #[command(flatten)]
75	    pub dry_run: DryRunFlag,
76	}
77	
78	/// Inputs to the `bookmark delete` op, flat, owned, clap-free.
79	#[derive(Debug)]
80	pub struct DeleteBookmarkParams {
81	    pub repos: Vec<PathBuf>,
82	    pub bookmark: String,
83	    pub skip: Option<Keep>,
84	    pub dry_run: bool,
85	}
86	
87	impl TryFrom<&DeleteArgs> for DeleteBookmarkParams {
88	    type Error = String;
89	
90	    /// Resolve the scope to its repos ([`bookmark_repos`]).
91	    fn try_from(a: &DeleteArgs) -> Result<Self, String> {
92	        Ok(DeleteBookmarkParams {
93	            repos: bookmark_repos(a.scope.as_ref(), a.repo.as_deref(), LABEL, None)?,
94	            bookmark: a.bookmark.clone(),
95	            skip: a.skip,
96	            dry_run: a.dry_run.value,
97	        })
98	    }
99	}
100	
101	impl SubcommandRunner for DeleteArgs {
102	    type Params = DeleteBookmarkParams;
103	
104	    /// Delegate to the `TryFrom<&DeleteArgs>` impl above.
105	    fn to_params(&self) -> Result<Self::Params, String> {
106	        DeleteBookmarkParams::try_from(self)
107	    }
108	
109	    /// Run the `bookmark delete` op.
110	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
111	        debug!("{LABEL}: enter {params:?}");
112	        for repo in &params.repos {
113	            delete_bookmark(ctx, repo, &params.bookmark, params.skip, params.dry_run)?;
114	        }
115	        Ok(())
116	    }
117	}
118	
119	/// Delete `name` in `repo`, the remote then the local, `skip` keeping
120	/// one side, printing the commit it was at so the deletion can be
121	/// undone. A side already gone is no error, and a bookmark gone on
122	/// both sides is reported and left.
123	pub fn delete_bookmark(
124	    ctx: &mut Context,
125	    repo: &Path,
126	    name: &str,
127	    skip: Option<Keep>,
128	    dry_run: bool,
129	) -> Result<(), Box<dyn std::error::Error>> {
130	    let local = jj::local_bookmark_exists(repo, name)?;
131	    let remote = jj::remote_bookmark_targets(repo, "origin")?
132	        .get(name)
133	        .cloned();
134	    let at = if local {
135	        Some(jj::cid_of(repo, name)?)
136	    } else {
137	        remote.clone()
138	    };
139	    let (del_remote, del_local) = (
140	        remote.is_some() && skip != Some(Keep::Remote),
141	        local && skip != Some(Keep::Local),
142	    );
143	    if !del_remote && !del_local {
144	        warn!(
145	            "{LABEL}: '{name}' has nothing to delete in {}, as asked",
146	            repo.display()
147	        );
148	        return Ok(());
149	    }
150	    let at = at.unwrap_or_default();
151	    let dry = if dry_run { "[dry-run] " } else { "" };
152	    if del_remote {
153	        info!("{LABEL}: {dry}delete '{name}' on origin, at {at}");
154	    }
155	    if del_local {
156	        info!("{LABEL}: {dry}delete '{name}' locally, at {at}");
157	    }
158	    if dry_run {
159	        return Ok(());
160	    }
161	    if del_remote {
162	        ctx.session(repo)?.git_push_delete_bookmark(name)?;
163	    }
164	    if del_local {
165	        ctx.session(repo)?.bookmark_delete(name)?;
166	    }
167	    info!("{LABEL}: done, `jj bookmark set {name} -r {at}` would bring it back");
168	    Ok(())
169	}
170	
171	#[cfg(test)]
172	mod tests {
173	    use super::*;
174	    use crate::test_helpers::{Fixture, jj_ok, test_ctx};
175	
176	    /// Where `name` is, locally and on origin, as commit ids.
177	    fn state(repo: &Path, name: &str) -> (bool, bool) {
178	        (
179	            jj::local_bookmark_exists(repo, name).expect("local"),
180	            jj::remote_bookmark_targets(repo, "origin")
181	                .expect("remote")
182	                .contains_key(name),
183	        )
184	    }
185	
186	    /// A published bookmark in the fixture's work repo.
187	    fn published(fx: &Fixture, name: &str) {
188	        jj_ok(&fx.work, &["git", "push", "--named", &format!("{name}=@-")]);
189	        assert_eq!(state(&fx.work, name), (true, true));
190	    }
191	
192	    /// Both sides go by default, `--skip` keeps the one it names, a
193	    /// side already gone is no error, and a dry run changes nothing.
194	    #[test]
195	    fn a_bookmark_is_deleted_locally_and_on_origin() {
196	        let fx = Fixture::new("bm-delete");
197	        published(&fx, "both");
198	        delete_bookmark(&mut test_ctx(), &fx.work, "both", None, true).expect("dry run");
199	        assert_eq!(
200	            state(&fx.work, "both"),
201	            (true, true),
202	            "a dry run changes nothing"
203	        );
204	        delete_bookmark(&mut test_ctx(), &fx.work, "both", None, false).expect("deleted");
205	        assert_eq!(state(&fx.work, "both"), (false, false));
206	        delete_bookmark(&mut test_ctx(), &fx.work, "both", None, false).expect("gone already");
207	
208	        published(&fx, "keep-local");
209	        delete_bookmark(
210	            &mut test_ctx(),
211	            &fx.work,
212	            "keep-local",
213	            Some(Keep::Local),
214	            false,
215	        )
216	        .expect("remote deleted");
217	        assert_eq!(state(&fx.work, "keep-local"), (true, false));
218	
219	        published(&fx, "keep-remote");
220	        delete_bookmark(
221	            &mut test_ctx(),
222	            &fx.work,
223	            "keep-remote",
224	            Some(Keep::Remote),
225	            false,
226	        )
227	        .expect("local deleted");
228	        assert_eq!(state(&fx.work, "keep-remote"), (false, true));
229	    }
230	}
